#!/usr/bin/env bash
# release.yaml's legion_build releases a new `legion` only when a commit since the newest legion-v*
# tag touches one of the paths its version step hands `release-push.sh version`: those after `--`
# in $LEGION_VERSION_ARGS, written by hand, and then $LEGION_GO_INPUTS. The binary compiles in
# packages of the envoy module too, and those were a list kept by hand that fell behind: main at
# 4055c4a523 named 14 of the 17 packages/envoy packages `go list -deps ./cmd/legion` names, so a
# change to internal/ctxlock, internal/dispatch/bytelru or internal/fold changed the binary and
# released nothing (INFRA-3904).
#
# So $LEGION_GO_INPUTS is a generated block of release.yaml's workflow `env:`, from a
# `# BEGIN generated by ...` line to `# END generated`, and this check holds it to what go says.
# The block holds every path below that no path after `--` in $LEGION_VERSION_ARGS covers (one
# covers itself and the tree under it, as a git pathspec does), one a line, sorted:
#   * the directory of every package of this repository that `go list -deps ./cmd/legion`, run in
#     packages/daemon, names for a target of .github/go-release-targets.json's `legion` list under
#     CGO_ENABLED=0, as the Build legion step compiles them: a file that one target's build
#     constraints alone compile can import a package that no other target links. A directory
#     stands for the package's files, its embedded ones among them, since go:embed reads nothing
#     outside it;
#   * the files that decide which version of each module the binary links: the workspace's go.work
#     and go.work.sum (`go env GOWORK`: the build runs in packages/daemon under the root go.work),
#     and the go.mod and go.sum of every module `go list -m` names there and of every module that
#     provides one of those packages, each one that exists.
#
# Fails on:
#   1. a block that is not exactly the one `write` writes, naming every path it lacks and every
#      path it names that go does not, or a release.yaml with no such block or more than one;
#   2. a block that is not the LEGION_GO_INPUTS of the workflow's `env:`, or a path after `--` in
#      $LEGION_VERSION_ARGS that is a pathspec with magic (`:(exclude)...`), which this check
#      cannot read;
#   3. legion_build's version step not handing the block to `release-push.sh version legion-v`
#      right after $LEGION_VERSION_ARGS, since then no release reads it;
#   4. a go command that fails, or a package of this repository that go list cannot load, since
#      the set is then unknown; and a listing for a target that does not name cmd/legion itself,
#      since a listing that names nothing of the program would pass everything.
#
# The go commands run as .github/scripts/check-ci-filters.sh's do, and its header says why: with
# GOPROXY=off over an empty module cache, so nothing is downloaded and a cold runner gives the
# answer a warm machine does. A third-party package then fails to load, which loses no package of
# this repository, since no module outside it imports one. The toolchain the module pins is
# resolved first, under this machine's own cache and proxy, and its own binary runs every go
# command under GOTOOLCHAIN=local.
#
# THE TWO MODES. `check`, the default a bare call takes, is every refusal above. `write` rewrites
# the block in release.yaml instead of refusing rule 1, and refuses everything else as `check`
# does; it writes nothing when rule 2's pathspec or rule 4 refuses, since the block would then be
# computed from a set that is unknown. It writes only inside the block. Any other word, or more
# than one, fails.
#
# Run from anywhere: .github/scripts/check-legion-version-inputs.sh
#                    .github/scripts/check-legion-version-inputs.sh write
# CI runs it in ci.yaml's ci-filters job, and its tests in ci.yaml's test job.
set -euo pipefail

cd "$(dirname "$0")/../.."

# A bare call checks: a caller who says nothing is asking for the verdict, never for a rewrite of
# release.yaml.
case "$#:${1:-}" in
  0: | 1:check | 1:write) ;;
  *)
    echo "::error file=.github/scripts/check-legion-version-inputs.sh::this check takes one optional mode: \`check\` (the default) refuses a LEGION_GO_INPUTS block of release.yaml that is not what go names, and \`write\` writes that block instead. Run \`.github/scripts/check-legion-version-inputs.sh\` or \`.github/scripts/check-legion-version-inputs.sh write\`." >&2
    exit 1
    ;;
esac

PYTHONDONTWRITEBYTECODE=1 exec python3 - "${1:-check}" <<'PY'
import json
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

import yaml

MODE = sys.argv[1]
SELF = ".github/scripts/check-legion-version-inputs.sh"
RELEASE = ".github/workflows/release.yaml"
TARGETS = ".github/go-release-targets.json"
DAEMON = "packages/daemon"
PROGRAM = "./cmd/legion"
HAND = "LEGION_VERSION_ARGS"
BLOCK = "LEGION_GO_INPUTS"
JOB = "legion_build"
STEP_ID = "version"
HANDOFF = f".github/scripts/release-push.sh version legion-v ${HAND} ${BLOCK}"
BEGIN = f"  # BEGIN generated by `{SELF} write`"
END = "  # END generated"
HEAD = [
    f"{BEGIN}: what go",
    f"  # decides the binary from beyond ${HAND}'s paths, one path a line. An edit by",
    "  # hand is refused: that check, which the ci-filters job runs, names what go adds or drops.",
]
REPO = Path.cwd().resolve()
problems = []


def annotation(path, message, line=None):
    where = f"file={path}" + (f",line={line}" if line else "")
    return f"::error {where}::{message}"


def problem(message, line=None, path=RELEASE):
    problems.append(annotation(path, message, line))


def fatal(message, path=RELEASE):
    print(annotation(path, message), file=sys.stderr)
    raise SystemExit(1)


def read(path):
    try:
        return Path(path).read_text(encoding="utf-8")
    except FileNotFoundError:
        fatal(f"{path} is missing", path)
    except UnicodeDecodeError as error:
        fatal(f"{path} is not readable as text: {error.reason}", path)


def load(path, text):
    try:
        return yaml.safe_load(text)
    except yaml.YAMLError as error:
        fatal(f"{path} is not YAML this check can read: {' '.join(str(error).split())}", path)


def rel(path):
    """`path` relative to the repository's root, or None when it is outside it."""
    try:
        return Path(path).resolve().relative_to(REPO).as_posix()
    except ValueError:
        return None


def covers(hand, path):
    """Whether the pathspec `hand` matches `path`, a file or a directory written with its /."""
    hand, path = hand.rstrip("/"), path.rstrip("/")
    return path == hand or path.startswith(hand + "/")


def decode_stream(text):
    decoder, index, out = json.JSONDecoder(), 0, []
    while True:
        while index < len(text) and text[index].isspace():
            index += 1
        if index >= len(text):
            return out
        obj, index = decoder.raw_decode(text, index)
        out.append(obj)


# --- what release.yaml says
text = read(RELEASE)
lines = text.split("\n")
doc = load(RELEASE, text)
env = doc.get("env") if isinstance(doc, dict) else None
if not isinstance(env, dict) or not isinstance(env.get(HAND), str):
    fatal(f"{RELEASE}'s workflow env: holds no {HAND} string")
words = env[HAND].split()
if "--" not in words:
    fatal(f"{RELEASE}'s {HAND} has no `--`, after which release-push.sh version reads its paths")
hand_paths = words[words.index("--") + 1:]
for path in hand_paths:
    if path.startswith(":"):
        problem(f"{HAND} names `{path}`, a pathspec with magic, which this check cannot read: it "
                f"may exclude a path {BLOCK} names, which git would then leave out of every release")
plain = [path for path in hand_paths if not path.startswith(":")]

# --- what go says
modcache = tempfile.mkdtemp(prefix="check-legion-version-inputs-")
try:
    try:
        found = subprocess.run(["go", "env", "GOROOT"], cwd=DAEMON, capture_output=True, text=True, check=False)
    except FileNotFoundError:
        fatal(f"no go on PATH, so what {DAEMON}'s {PROGRAM} links is unknown", SELF)
    root = found.stdout.strip()
    go_bin = Path(root) / "bin" / "go" if root else None
    if found.returncode != 0 or not go_bin or not go_bin.is_file():
        fatal(f"`go env GOROOT` in {DAEMON} names no toolchain ({' '.join(found.stderr.split())[:500]}), "
              f"so what {PROGRAM} links is unknown", SELF)

    def go(args, **extra):
        environment = dict(os.environ, GOPROXY="off", GOMODCACHE=modcache, GOFLAGS="", GOWORK="",
                           GOTOOLCHAIN="local", **extra)
        result = subprocess.run([str(go_bin), *args], cwd=DAEMON, env=environment,
                                capture_output=True, text=True, check=False)
        if result.returncode != 0:
            fatal(f"in {DAEMON}, go {' '.join(args)} failed, so what {PROGRAM} links is unknown: "
                  f"{' '.join(result.stderr.split())[:500]}", SELF)
        return result.stdout

    try:
        targets = json.loads(read(TARGETS))["legion"]
    except (ValueError, KeyError, TypeError):
        targets = None
    if not isinstance(targets, list) or not targets or not all(isinstance(t, str) and t.count("/") == 1 for t in targets):
        fatal(f"{TARGETS} holds no `legion` list of os/arch targets", TARGETS)

    modules = [line.split("\t") for line in go(["list", "-m", "-f", "{{.Path}}\t{{.Dir}}\t{{.GoMod}}"]).splitlines() if line]
    first_party = [path for path, _, _ in modules]
    files = set()
    gowork = go(["env", "GOWORK"]).strip()
    if gowork and gowork != "off":
        files |= {gowork, gowork + ".sum"}
    gomods = {gomod for _, _, gomod in modules if gomod}
    directories = set()
    program = (REPO / DAEMON / PROGRAM).resolve()
    for target in targets:
        goos, goarch = target.split("/")
        listing = decode_stream(go(["list", "-e", "-deps", "-json=ImportPath,Dir,Module,Error", PROGRAM],
                                   GOOS=goos, GOARCH=goarch, CGO_ENABLED="0"))
        if not any(pkg.get("Dir") and Path(pkg["Dir"]).resolve() == program for pkg in listing):
            fatal(f"go list -deps {PROGRAM} for {target} named no package in {DAEMON}/cmd/legion, so what "
                  f"it links is unknown", SELF)
        for pkg in listing:
            name = pkg.get("ImportPath", "")
            directory = rel(pkg["Dir"]) if pkg.get("Dir") else None
            ours = directory is not None or any(name == m or name.startswith(m + "/") for m in first_party)
            if ours and pkg.get("Error"):
                problem(f"go list cannot load {name} for {target}, so what {PROGRAM} links is unknown: "
                        f"{' '.join(str(pkg['Error'].get('Err', '')).split())[:500]}", path=SELF)
            if directory is None:
                continue
            directories.add(directory + "/")
            if (pkg.get("Module") or {}).get("GoMod"):
                gomods.add(pkg["Module"]["GoMod"])
    for gomod in gomods:
        files |= {gomod, str(Path(gomod).parent / "go.sum")}
finally:
    shutil.rmtree(modcache, True)

if problems:
    print("\n".join(problems), file=sys.stderr)
    raise SystemExit(1)

found_files = {rel(path) for path in files if Path(path).is_file()} - {None}
inputs = sorted(path for path in directories | found_files if not any(covers(hand, path) for hand in plain))
body = [f"  {BLOCK}: >-", *(f"    {path}" for path in inputs)] if inputs else [f'  {BLOCK}: ""']
want = [*HEAD, *body, END]

# --- the block
begins = [i for i, line in enumerate(lines) if line.startswith(BEGIN)]
if len(begins) != 1:
    fatal(f"{RELEASE} must hold one block from `{BEGIN.strip()}` to `{END.strip()}`, which {SELF} write "
          f"fills; it holds {len(begins)}")
begin = begins[0]
end = next((i for i in range(begin + 1, len(lines)) if lines[i] == END), None)
if end is None:
    fatal(f"{RELEASE}'s block from line {begin + 1} has no `{END.strip()}` line")
have = lines[begin:end + 1]
if have != want:
    if MODE == "write":
        lines[begin:end + 1] = want
        text = "\n".join(lines)
        Path(RELEASE).write_text(text, encoding="utf-8")
        doc = load(RELEASE, text)
        env = doc.get("env") if isinstance(doc, dict) else None
        print(f"wrote {RELEASE}'s {BLOCK}: {len(inputs)} paths")
    else:
        # The block's paths are its lines indented as the folded value's, comments aside.
        held = {line.strip() for line in have if line.startswith("    ") and not line.lstrip().startswith("#")}
        lacks = [path for path in inputs if path not in held]
        extra = sorted(held - set(inputs))
        parts = ([f"it lacks {', '.join(lacks)}, which go names"] if lacks else []) + (
            [f"it names {', '.join(extra)}, which go does not"] if extra else [])
        problem(f"{BLOCK} is not what go decides the legion binary from beyond {HAND}'s paths: "
                f"{'; '.join(parts) or 'its text is not the block write writes'}; run `{SELF} write`",
                line=begin + 1)
elif MODE == "write":
    print(f"{RELEASE}'s {BLOCK} already holds what go names: {len(inputs)} paths")

if have == want or MODE == "write":
    value = env.get(BLOCK) if isinstance(env, dict) else None
    if not isinstance(value, str) or value.split() != inputs:
        problem(f"the block from line {begin + 1} is not the {BLOCK} of {RELEASE}'s workflow env:, "
                f"which legion_build's version step reads", line=begin + 1)

# --- the version step reads it
jobs = doc.get("jobs") if isinstance(doc, dict) else None
steps = ((jobs or {}).get(JOB) or {}).get("steps") or []
runs = [step.get("run") for step in steps if isinstance(step, dict) and step.get("id") == STEP_ID]
if len(runs) != 1 or not isinstance(runs[0], str) or HANDOFF not in " ".join(runs[0].split()):
    problem(f"{JOB}'s step `{STEP_ID}` must run `{HANDOFF}`: {BLOCK} decides a release only "
            f"where that step hands it to release-push.sh after {HAND}")

if problems:
    print("\n".join(problems), file=sys.stderr)
    raise SystemExit(1)
packages = sum(path.endswith("/") for path in inputs)
print(f"{RELEASE}'s {BLOCK} is what go decides the legion binary from beyond {HAND}'s paths: "
      f"{packages} package directories and {len(inputs) - packages} module files, over {', '.join(targets)}")
PY
